import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.CZxGLIO_.js";const u=JSON.parse('{"title":"故障排查","description":"按启动、注册、代理、MFA、存储与升级症状定位 GooseForum 问题。","frontmatter":{"title":"故障排查","description":"按启动、注册、代理、MFA、存储与升级症状定位 GooseForum 问题。"},"headers":[],"relativePath":"docs/gooseforum/troubleshooting/index.md","filePath":"docs/gooseforum/troubleshooting/index.md"}'),s={name:"docs/gooseforum/troubleshooting/index.md"};function d(i,e,n,h,l,c){return t(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="故障排查" tabindex="-1">故障排查 <a class="header-anchor" href="#故障排查" aria-label="Permalink to &quot;故障排查&quot;">​</a></h1><p>先记录版本、运行目录、数据库类型、最近变更和错误时间，再查看相应日志。分享日志前移除密码、Cookie、令牌、连接串和邮件凭据。</p><h2 id="服务无法启动或出现新空站点" tabindex="-1">服务无法启动或出现新空站点 <a class="header-anchor" href="#服务无法启动或出现新空站点" aria-label="Permalink to &quot;服务无法启动或出现新空站点&quot;">​</a></h2><p>使用 systemd 时查看 <code>systemctl status gooseforum</code> 和 <code>journalctl -u gooseforum -n 100 --no-pager</code>。核对端口占用、TOML 语法、文件权限与数据库可用性。</p><p>如果服务能启动却没有原来的主题，检查 <code>WorkingDirectory</code>、实际加载的 <code>config.toml</code>、SQLite 路径或外部数据库名。不要在尚未确认路径时继续注册、迁移或覆盖数据库。</p><h2 id="注册失败、验证邮件不到或频繁限流" tabindex="-1">注册失败、验证邮件不到或频繁限流 <a class="header-anchor" href="#注册失败、验证邮件不到或频繁限流" aria-label="Permalink to &quot;注册失败、验证邮件不到或频繁限流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>症状</th><th>检查方向</th></tr></thead><tbody><tr><td>新账号无法创建</td><td>注册开关、邮箱域名精确匹配、SMTP 是否配置</td></tr><tr><td>OAuth 首次登录失败</td><td>上游是否提供有效邮箱、是否与已有账号冲突、是否允许注册</td></tr><tr><td>所有用户像共用一个 IP</td><td>反代地址是否列入 <code>server.trustedProxies</code></td></tr><tr><td>邮件测试成功但实际未生效</td><td>测试使用当前表单值，确认之后已保存</td></tr><tr><td>收到 SMTP 成功却没邮件</td><td>收件箱、垃圾邮件、发送记录和退信，成功提交不等于送达</td></tr><tr><td>待验证用户无法登录</td><td>正确密码与验证码可触发重发，仍受冷却与邮件配额约束</td></tr></tbody></table><p>先解决配置和投递问题，再重试注册或登录；不要通过反复重启清空限额来代替定位原因。具体默认值见 <a href="./../security/">账号安全</a>。</p><h2 id="双因素认证失败" tabindex="-1">双因素认证失败 <a class="header-anchor" href="#双因素认证失败" aria-label="Permalink to &quot;双因素认证失败&quot;">​</a></h2><p>检查服务器和手机时间、是否重复使用上一枚验证码、当前挑战是否已经过期。服务重启会清空挑战，需要重新开始登录。</p><p>升级后所有 MFA 用户同时失败，优先确认是否误改了 <code>[app].secretKey</code> 或旧 <code>signingKey</code> 的值。恢复原密钥，不能靠生成新密钥解密旧数据。丢失个人验证器按 <a href="./../security/">恢复流程</a> 处理，改密码不会移除 MFA。</p><h2 id="图片或附件异常" tabindex="-1">图片或附件异常 <a class="header-anchor" href="#图片或附件异常" aria-label="Permalink to &quot;图片或附件异常&quot;">​</a></h2><p>数据库存储时核对数据库连接和文件记录；S3 存储时分别检查服务端 endpoint、凭据、桶、浏览器可访问的 publicUrl 与对象权限。</p><p>直传请求失败时检查浏览器网络面板中的预签名 <code>PUT</code>，桶 CORS 是否允许站点来源、<code>PUT</code> 和 <code>Content-Type</code>。上传超时还需核对应用 HTTP 超时、文件大小限制及代理限制。</p><h2 id="更新后页面不一致" tabindex="-1">更新后页面不一致 <a class="header-anchor" href="#更新后页面不一致" aria-label="Permalink to &quot;更新后页面不一致&quot;">​</a></h2><p>确认前端与后端属于同一构建，实际运行的可执行文件已更新，代理没有长期缓存 HTML 或状态接口。先保存未提交内容，再使用页面刷新入口。仅在源码目录运行前端构建，不会修改旧二进制中的资源。</p><h2 id="管理员账号恢复" tabindex="-1">管理员账号恢复 <a class="header-anchor" href="#管理员账号恢复" aria-label="Permalink to &quot;管理员账号恢复&quot;">​</a></h2><p>服务器管理员可在<strong>原运行目录</strong>使用以下命令；<code>42</code> 是占位用户 ID，必须先核对目标用户：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./GooseForum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-user-admin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./GooseForum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set-user-password</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 42</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;REPLACE_WITH_A_NEW_PASSWORD&#39;</span></span></code></pre></div><p>只运行需要的命令，不要原样使用示例密码。密码作为命令行参数可能进入 shell 历史和进程参数，应在受控维护终端操作。独立 CLI 改密后，服务内认证缓存最多有 15 秒失效延迟。上述命令不重置 MFA。</p><h2 id="报告问题时附带的信息" tabindex="-1">报告问题时附带的信息 <a class="header-anchor" href="#报告问题时附带的信息" aria-label="Permalink to &quot;报告问题时附带的信息&quot;">​</a></h2><p>提供版本或提交 SHA、系统和 CPU、数据库类型、复现步骤、预期与实际结果、脱敏日志。界面问题附带浏览器版本和失败请求状态码。源码与问题反馈入口：<a href="https://github.com/leancodebox/GooseForum/issues" target="_blank" rel="noreferrer">GooseForum</a>。</p><hr><p>核对日期：2026-11-15；依据当前源码：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/app/console/cmd/user.go" target="_blank" rel="noreferrer">用户命令</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/registration-controls.md" target="_blank" rel="noreferrer">注册与邮件</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/two-factor-authentication.md" target="_blank" rel="noreferrer">MFA</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/configuration_ZH.md" target="_blank" rel="noreferrer">配置</a>。</p>`,24)])])}const b=a(s,[["render",d]]);export{u as __pageData,b as default};
